/// <summary>
/// the <C>METPickupAdviceReportContract</C> class used as data contract class to run the pickup advice report
/// </summary>
[DataContractAttribute]

class METPickupAdviceReportContract extends METCommonReportContract
{
    WHSShipmentId       shipmentID;
    SalesIdBase         salesID;

}

Method.Source:
/// <summary>
/// parm method to get set WHSShipmentId.
/// </summary>
/// <param name = "_shipmentID">WHSShipmentId</param>
/// <returns>WHSShipmentId</returns>
[
    DataMemberAttribute('WHSShipmentId'),
    SysOperationLabelAttribute('Shipment ID')
]
public WHSShipmentId parmShipmentID(WHSShipmentId _shipmentID  = shipmentID)
{
    shipmentID   =   _shipmentID;
    return  shipmentID;
}

//Added parameter for the sales order id - task 237151 ----------------->
/// <summary>
/// parm method to get set SalesIdBase.
/// </summary>
/// <param name = "_salesID">SalesIdBase</param>
/// <returns>SalesIdBase</returns>
[
    DataMemberAttribute('SalesIdBase'),
    SysOperationLabelAttribute('Sales ID')
]
public SalesIdBase parmSalesID(SalesIdBase _salesID  = salesID)
{
    salesID   =   _salesID;
    return  salesID;
}
